def _flatten(nested_list):
    """Recursively flatten a nested list of lists/tuples."""
    flat = []
    for item in nested_list:
        if isinstance(item, (list, tuple)):
            flat.extend(_flatten(item))
        else:
            flat.append(item)
    return flat


def check_subset_list(list1, list2):
    """Write a function to check if a nested list is a subset of another nested list."""
    flat1 = _flatten(list1)
    flat2 = _flatten(list2)
    return all(item in flat2 for item in flat1)
